-- 2026-10-18 MES只读预检；仅供另行授权的操作者核实，不由开发工具执行。
-- 不建立连接、不改表、不修复、不切换STRICT。先核对目标及导出边界。
SELECT DATABASE() AS selected_database,@@server_uuid AS server_uuid,VERSION() AS mysql_version;
SELECT TABLE_NAME,ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('lt_wo_consumption','pro_sn','mes_label_template','mes_label_print_log','lt_lot','pro_completion_manifest','pro_completion_manifest_line','lt_sn_consumption','lt_sn_material_guard','lt_lot_allocation','mes_trace_outbox','mes_trace_inbox','mes_trace_repair_run','mes_trace_repair_item','mes_label_print_task','pro_completion_material_allocation','pro_product_lot_output');
SELECT TABLE_NAME,COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT,COLLATION_NAME,EXTRA,GENERATION_EXPRESSION FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('lt_wo_consumption','pro_sn','mes_label_template','mes_label_print_log','lt_lot','pro_completion_manifest','pro_completion_manifest_line','lt_sn_consumption','lt_sn_material_guard','lt_lot_allocation','mes_trace_outbox','mes_trace_inbox','mes_trace_repair_run','mes_trace_repair_item','mes_label_print_task','pro_completion_material_allocation','pro_product_lot_output') ORDER BY TABLE_NAME,ORDINAL_POSITION;
SELECT TABLE_NAME,INDEX_NAME,NON_UNIQUE,SEQ_IN_INDEX,COLUMN_NAME,SUB_PART FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('lt_wo_consumption','pro_sn','mes_label_template','mes_label_print_log','lt_lot','pro_completion_manifest','pro_completion_manifest_line','lt_sn_consumption','lt_sn_material_guard','lt_lot_allocation','mes_trace_outbox','mes_trace_inbox','mes_trace_repair_run','mes_trace_repair_item','mes_label_print_task','pro_completion_material_allocation','pro_product_lot_output') ORDER BY TABLE_NAME,INDEX_NAME,SEQ_IN_INDEX;
SELECT tenant_id,sn_id,source,mes_wo_id FROM pro_sn WHERE mes_wo_id IS NULL AND COALESCE(source,'')<>'SUBCONTRACT';
SET @trace_preflight_sql=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='pro_sn' AND COLUMN_NAME='identity_id')=1,'SELECT tenant_id,identity_id,COUNT(*) AS conflicting_rows FROM pro_sn WHERE identity_id IS NOT NULL GROUP BY tenant_id,identity_id HAVING COUNT(*)>1','SELECT ''旧基线尚无identity_id，不能根据同码补造映射'' AS preflight_note');
PREPARE trace_preflight_stmt FROM @trace_preflight_sql;
EXECUTE trace_preflight_stmt;
DEALLOCATE PREPARE trace_preflight_stmt;
